-- New Surya Sweets 2025 menu import
-- Source: New Surya Menu new Price - 2025.xlsx
-- POS Menu 2025 drives walk-in/takeaway; Online Menu 2025 drives Swiggy/Zomato/website.

begin;

alter table public.products add column if not exists code text;
alter table public.products add column if not exists sell_by_weight boolean not null default false;
alter table public.products add column if not exists allow_in_store boolean not null default true;
alter table public.products add column if not exists pack_size text;
alter table public.products add column if not exists source_sheet text;
alter table public.products add column if not exists image_url text;
alter table public.products add column if not exists contains_allergen text;

create unique index if not exists products_code_unique on public.products(code) where code is not null;
create index if not exists products_active_category_idx on public.products(active, category);
create index if not exists branch_prices_product_idx on public.branch_prices(product_id);

